import{_ as r,C as i,o,c as s,j as a,a as h,E as n,a3 as l}from"./chunks/framework.Ba39LDvt.js";const f=JSON.parse('{"title":"CS110 计算机体系结构 I 及课程设计","description":"连接 C、RISC-V、CPU、存储层次与并行计算，介绍 CS110 和 CS110P 的学习与项目节奏。","frontmatter":{"title":"CS110 计算机体系结构 I 及课程设计","description":"连接 C、RISC-V、CPU、存储层次与并行计算，介绍 CS110 和 CS110P 的学习与项目节奏。"},"headers":[],"relativePath":"courses/cs110.md","filePath":"courses/cs110.md","lastUpdated":1795525517000}'),d={name:"courses/cs110.md"};function c(u,t,C,g,S,b){const e=i("CourseTable");return o(),s("div",null,[t[0]||(t[0]=a("h1",{id:"cs110-计算机体系结构-i-及课程设计",tabindex:"-1"},[h("CS110 计算机体系结构 I 及课程设计 "),a("a",{class:"header-anchor",href:"#cs110-计算机体系结构-i-及课程设计","aria-label":'Permalink to "CS110 计算机体系结构 I 及课程设计"'},"​")],-1)),n(e,{codes:"CS110,CS110P"}),t[1]||(t[1]=l('<p>课程表采用 <strong>2026–2027 学年</strong>信息；详细内容与评分参照公开的 <strong>2026 春版本</strong>课程主页。往届版本教师可能不同，CS110 与 CS110P 需分别核对注册与考核要求。</p><h2 id="课程定位" tabindex="-1">课程定位 <a class="header-anchor" href="#课程定位" aria-label="Permalink to &quot;课程定位&quot;">​</a></h2><p>CS110 研究数字计算机如何组织和执行程序，把“代码能运行”推进到“为什么得到这个结果、时间花在哪里、硬件怎样实现”。官方先修为 CS100；学习时需要较扎实的 C 编程基础。</p><p><a href="/shanghaitech-ic-wiki-dev.github.io/courses/si100b">SI100B</a>与<a href="/shanghaitech-ic-wiki-dev.github.io/courses/ee115b">EE115B</a>能提供硬件直觉，但课程并不是单纯的数字逻辑复习。它向后连接操作系统、并行计算，以及<a href="/shanghaitech-ic-wiki-dev.github.io/courses/ee219">EE219 智能计算系统</a>。对于 EE 学生，应按本年级培养方案确认其学分归类，不因开课表写“必修”就视为 EE 专业必修。</p><h2 id="内容主线" tabindex="-1">内容主线 <a class="header-anchor" href="#内容主线" aria-label="Permalink to &quot;内容主线&quot;">​</a></h2><p>以下按 2026 春官网周历归并：</p><table tabindex="0"><thead><tr><th>周次</th><th>知识主线</th><th>建议达到的能力</th></tr></thead><tbody><tr><td>1–2</td><td>信息表示、C、内存管理</td><td>解释整数与浮点表示，跟踪指针、栈和堆</td></tr><tr><td>3–4</td><td>RISC-V、调用约定、编译汇编链接加载</td><td>从 C 行为对应到寄存器、指令和函数调用</td></tr><tr><td>5–6</td><td>数字逻辑、数据通路与控制器</td><td>沿单周期 CPU 跟踪一条指令</td></tr><tr><td>7–8</td><td>流水线与多发射</td><td>分析数据 / 控制冒险、转发和停顿</td></tr><tr><td>9–10</td><td>存储层次与高速缓存（Cache）</td><td>分解地址，判断命中与缺失并计算平均访问代价</td></tr><tr><td>11–13</td><td>SIMD、线程级并行、OpenMP、同步与多核</td><td>区分向量化、并行加速与同步开销</td></tr><tr><td>14–16</td><td>I/O、虚拟内存、仓库级计算、可靠性与异构计算</td><td>把单核知识放回完整系统</td></tr></tbody></table><p>性能分析应使用明确的工作量与时间口径。降低某段代码的指令数，不一定降低总执行时间；改变访存和并行策略时尤其如此。</p><h2 id="实验-项目" tabindex="-1">实验 / 项目 <a class="header-anchor" href="#实验-项目" aria-label="Permalink to &quot;实验 / 项目&quot;">​</a></h2><p>CS110 的 Lab 与 CS110P 的 Project 在课程主页并列组织，但评分不同。2026 春课程设计包含多个分阶段项目；笔记记录了 CPU 性能优化与 Longan Nano 开发板实践。</p><p><strong>Project 4：Snake Game</strong> 使用 C 与 RISC-V 汇编，借助 PlatformIO 交叉编译并烧录至 Longan Nano。项目要求独立完成，采用现场人工检查。重点不只是游戏画面，还包括指定的汇编逻辑、输入处理、状态切换及可重复构建。</p><p>建议先打通编译、烧录、按键与屏幕最小链路，再增加玩法；将状态更新和绘制分离，分别验证。最终必须从实际提交包重新构建，不能依赖工作目录里未提交的资源文件。实验与项目的具体限制、代码模板和检查标准以当学期任务书为准。</p><h2 id="教材与资源" tabindex="-1">教材与资源 <a class="header-anchor" href="#教材与资源" aria-label="Permalink to &quot;教材与资源&quot;">​</a></h2><ul><li>Patterson / Hennessy，<em>Computer Organization and Design</em>，RISC-V 版：官网列出的主教材。</li><li>Kernighan / Ritchie，<em>The C Programming Language</em>：C 基础参考。</li><li>《深入理解计算机系统》：连接内存、程序执行与系统软件。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/liust/courses/CS110.html" target="_blank" rel="noreferrer">CS110 官方课程主页</a>：讲义、周历、Lab、Project 与最新通知。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/self-learning/architecture">体系结构自学</a>：用于补充路线，不替代课程的 ISA 与工具版本。</li></ul><h2 id="往届经验与建议" tabindex="-1">往届经验与建议 <a class="header-anchor" href="#往届经验与建议" aria-label="Permalink to &quot;往届经验与建议&quot;">​</a></h2><p><strong>2026 春版本。</strong> 官网列出 CS110 总评：Homework 40%、Lab 5%、两次期中各 14%、期末 25%、参与 2%。CS110P 为 P/NP，Project 1.1 / 1.2 各 17%，2.1 / 2.2 各 16%，3 / 4 各 17%。这些是不同课程的两套考核，不应相加。</p><ul><li><strong>节奏</strong>：作业占比较高且项目并行推进，不能只在考试前集中学习。</li><li><strong>难点</strong>：C 指针与内存错误、调用约定、流水线周期图、Cache 地址拆分和线程同步。</li><li><strong>准备</strong>：熟悉 Linux、Git、Makefile、调试器和交叉编译概念。出现错误时先定位到编译、链接、运行还是硬件接口阶段。</li><li><strong>性能实验</strong>：固定输入与线程数，先检查输出正确性，再报告时间；不能用一次偶然的最快结果代表稳定加速。</li><li><strong>诚信</strong>：个人项目独立实现；讨论原理与交换提交代码之间有明确边界。</li></ul><h2 id="相关方向" tabindex="-1">相关方向 <a class="header-anchor" href="#相关方向" aria-label="Permalink to &quot;相关方向&quot;">​</a></h2><ul><li><a href="/shanghaitech-ic-wiki-dev.github.io/research/architecture">计算机体系结构</a>：处理器、存储与并行系统。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/research/ai-hardware">AI 硬件</a>：将访存与并行知识用于加速器。</li><li><a href="/shanghaitech-ic-wiki-dev.github.io/research/digital-vlsi">数字 VLSI</a>：把微结构落实到电路实现。</li></ul><div class="info custom-block"><p class="custom-block-title">征集</p><p>如果你修过 CS110 / CS110P，欢迎通过<a href="/shanghaitech-ic-wiki-dev.github.io/about/contribute">参与共建</a>补充版本差异、调试方法与项目组织建议。不上传可直接提交的代码或答案包。</p></div><h2 id="参考与来源" tabindex="-1">参考与来源 <a class="header-anchor" href="#参考与来源" aria-label="Permalink to &quot;参考与来源&quot;">​</a></h2><ul><li><a href="https://faculty.sist.shanghaitech.edu.cn/liust/courses/CS110.html" target="_blank" rel="noreferrer">CS110 官方课程主页</a>：2026 春周历与评分。</li><li><a href="https://faculty.sist.shanghaitech.edu.cn/office/Academics/Courses/SIST_2026-2027_Courses.htm" target="_blank" rel="noreferrer">SIST 2026–2027 学年开课表</a>：当前课程表信息。</li><li>维护者笔记《计算机体系结构 CS110（CA）》《CS110 Project 4 — Snake Game (Longan Nano)》：往届项目与工具链经验。</li></ul>',22))])}const m=r(d,[["render",c]]);export{f as __pageData,m as default};
